"""Regenerate bilingual figure-specific notes, captions and supplementary ledger."""
from pathlib import Path
import csv,hashlib,json
P=Path(__file__).resolve().parent
def read(p):return json.loads((P/p).read_text())
def create():
 notes=P/'figure_notes';notes.mkdir(exist_ok=True)
 # Repair only descriptive metadata for a zero-advection control; scalar history is unchanged.
 p=P/'gas_transport_results/shelf_w8_e0p2_D10_dx0.4_dt0.5_diffusion_only.json';q=json.loads(p.read_text())
 for v in q['velocity_scales']:v.update(near_liquid_speed_p95_mm_s=0.,local_Re_p95=0.,local_Pe_p95=0.,advective_L_over_U_s=None)
 p.write_text(json.dumps(q,indent=2))
 h=read('hole_sweep_summary.json');g=read('gas_transport_summary.json');s=read('selection.json');r=read('gas_transport_results/shelf_w8_e0p2_D10_dx0.4_dt0.5.json');fine=read('gas_transport_results/shelf_w8_e0p2_D10_dx0.3_dt0.5.json');bench=read('gas_transport_results/analytic_benchmark.json')
 datasets={}
 def add(file,zh,en,methodzh,methoden,resultzh,resulten,axeszh,axesen,data,limitszh='',limitsen=''):
  datasets[file]=dict(ZH=zh,EN=en)
